INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Netzplantechnik immer nur für große IT-Projekte geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Projekte"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Netzplantechnik für ein IT-Projekt anwende?', 3, '[{"text": "Kritischen Pfad", "correct": true, "because": "Bestimmt Zeitplan"}, {"text": "Schnellste Planung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Netzplantechnik?', 5, '[{"text": "Aktivitäten", "correct": true, "because": "Definieren Aufgaben"}, {"text": "Abhängigkeiten", "correct": true, "because": "Zeigen Reihenfolge"}, {"text": "Büromöbel", "correct": false, "because": "Kein Element"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Netzplantechnik identifiziert den kritischen Pfad. b) Sie ist immer ungenau.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann präzise sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Netzplantechnik für ein IT-Projekt anwende?', 4, '[{"text": "Zeitplan", "correct": false, "because": "Kern der Methode"}, {"text": "Ressourcen", "correct": false, "because": "Beeinflussen Ablauf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Netzplantechnik nur für Softwareprojekte geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Projekte"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Netzplantechnik?', 3, '[{"text": "Projektoptimierung", "correct": true, "because": "Kürzt Zeitplan"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Planung wichtiger"}, {"text": "Weniger Aufgaben", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sind bei der Netzplantechnik entscheidend?', 5, '[{"text": "Kritischer Pfad", "correct": true, "because": "Bestimmt Dauer"}, {"text": "Vorgangsabfolge", "correct": true, "because": "Definiert Reihenfolge"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Netzplantechnik hilft bei der Zeitplanung. b) Sie ist immer komplex. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer komplex"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Netzplantechnik in einem IT-Projekt anzuwenden?', 4, '[{"text": "Aktivitätsliste", "correct": false, "because": "Definiert Aufgaben"}, {"text": "Zeitabschätzung", "correct": false, "because": "Bestimmt Dauer"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Netzplantechnik immer zeitaufwendig?', 2, '[{"text": "Nein", "correct": true, "because": "Kann effizient sein"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Umfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Netzplantechnik?', 4, '[{"text": "Kürzere Projektzeit", "correct": true, "because": "Optimiert Ablauf"}, {"text": "Ressourcenplanung", "correct": true, "because": "Verteilt Aufgaben"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Netzplantechnik nur für große Projekte geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Netzplantechnik effektiv anzuwenden?', 3, '[{"text": "CPM-Methode", "correct": true, "because": "Kritischer Pfad"}, {"text": "Schnellste Software", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Netzplantechnik zeigt Abhängigkeiten. b) Sie ist immer ungenau.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kann präzise sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Netzplantechnik?', 5, '[{"text": "Vorgangszeiten", "correct": true, "because": "Bestimmen Dauer"}, {"text": "Ressourcenverfügbarkeit", "correct": true, "because": "Beeinflusst Plan"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich die Netzplantechnik für ein IT-Projekt anwende?', 3, '[{"text": "Abhängigkeiten", "correct": false, "because": "Definieren Reihenfolge"}, {"text": "Zeitplan", "correct": false, "because": "Kern der Methode"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Netzplantechnik immer komplex?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Projekt"}, {"text": "Ja", "correct": false, "because": "Kann einfach sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Netzplantechnik nur für IT-Projekte geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Bereiche"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für die Netzplantechnik?', 4, '[{"text": "Kritischer Pfad", "correct": true, "because": "Bestimmt Zeitplan"}, {"text": "Schnellste Planung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
